<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Notification Preferences</title>
    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #f9fafb;
        }
        .form-field {
            margin-bottom: 2rem;
        }
        /* Custom focus ring for better visibility */
        .custom-focus:focus-within {
            outline: 2px solid #2563eb;
            outline-offset: 2px;
        }
        /* Hide native radio but keep it accessible */
        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border-width: 0;
        }
        .radio-card:hover {
            border-color: #d1d5db;
        }
        .radio-input:checked + .radio-label {
            border-color: #2563eb;
            background-color: #eff6ff;
            ring: 2px;
            ring-color: #2563eb;
        }
        .radio-input:focus-visible + .radio-label {
            outline: 2px solid #2563eb;
            outline-offset: 2px;
        }
    </style>
</head>
<body class="flex items-center justify-center min-h-screen p-4">
    <div id="root" class="w-full max-w-md"></div>

    <script type="text/babel">
        const { useState } = React;

        const RadioOption = ({ id, name, value, label, checked, onChange }) => (
            <div class="relative">
                <input
                    id={id}
                    type="radio"
                    name={name}
                    value={value}
                    checked={checked}
                    onChange={() => onChange(value)}
                    className="sr-only radio-input"
                    required
                />
                <label
                    htmlFor={id}
                    className={`radio-label flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all duration-200 ${
                        checked ? 'border-blue-600 bg-blue-50' : 'border-gray-200 bg-white'
                    }`}
                >
                    <span className={`w-4 h-4 mr-3 border rounded-full flex items-center justify-center ${
                        checked ? 'border-blue-600 bg-blue-600' : 'border-gray-300'
                    }`}>
                        {checked && <span className="w-1.5 h-1.5 bg-white rounded-full"></span>}
                    </span>
                    <span className="text-sm font-medium text-gray-900">{label}</span>
                </label>
            </div>
        );

        const RadioButtonGroup = ({ legend, options, name, value, onChange }) => (
            <div className="form-field">
                <fieldset className="space-y-4">
                    <legend className="text-base font-semibold text-gray-900 mb-4">
                        {legend} <span className="text-red-500" aria-hidden="true">*</span>
                    </legend>
                    <div className="grid gap-3">
                        {options.map((option) => (
                            <RadioOption
                                key={option.value}
                                id={`${name}-${option.value}`}
                                name={name}
                                value={option.value}
                                label={option.label}
                                checked={value === option.value}
                                onChange={onChange}
                            />
                        ))}
                    </div>
                </fieldset>
            </div>
        );

        const NotificationForm = () => {
            const [preference, setPreference] = useState('');
            const [status, setStatus] = useState('idle');

            const handleSubmit = (e) => {
                e.preventDefault();
                setStatus('submitting');

                // Simulate form submission
                setTimeout(() => {
                    setStatus('success');
                    console.log('Form submitted with preference:', preference);
                }, 800);
            };

            const options = [
                { label: 'Email', value: 'email' },
                { label: 'SMS', value: 'sms' },
                { label: 'Push Notifications', value: 'push' }
            ];

            if (status === 'success') {
                return (
                    <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 text-center" role="status">
                        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
                            </svg>
                        </div>
                        <h2 className="text-xl font-semibold text-gray-900 mb-2">Preferences saved!</h2>
                        <p className="text-gray-600 mb-6">We'll send your notifications via {preference}.</p>
                        <button 
                            onClick={() => {setStatus('idle'); setPreference('');}}
                            className="text-blue-600 font-medium hover:underline focus:outline-none focus:ring-2 focus:ring-blue-500 rounded"
                        >
                            Change preferences
                        </button>
                    </div>
                );
            }

            return (
                <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100">
                    <div className="mb-6">
                        <h1 className="text-2xl font-bold text-gray-900">Notification Settings</h1>
                        <p className="text-gray-500 mt-1">Manage how you stay updated.</p>
                    </div>

                    <form onSubmit={handleSubmit} noValidate={false}>
                        <RadioButtonGroup
                            legend="How do you prefer to receive notifications?"
                            name="notification-preference"
                            options={options}
                            value={preference}
                            onChange={setPreference}
                        />

                        <button
                            type="submit"
                            disabled={!preference || status === 'submitting'}
                            className={`w-full py-3 px-4 rounded-lg font-semibold text-white transition-all duration-200 ${
                                !preference || status === 'submitting'
                                    ? 'bg-gray-300 cursor-not-allowed'
                                    : 'bg-blue-600 hover:bg-blue-700 active:transform active:scale-[0.98]'
                            } focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2`}
                        >
                            {status === 'submitting' ? 'Saving...' : 'Save Preferences'}
                        </button>
                    </form>
                </div>
            );
        };

        const App = () => (
            <main>
                <NotificationForm />
            </main>
        );

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
