<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Notification Preferences - Clean & Accessible</title>
    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #f8fafc;
            color: #0f172a;
        }
        .form-field {
            margin-bottom: 2rem;
        }
        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border-width: 0;
        }
        .skip-link {
            position: absolute;
            top: -40px;
            left: 0;
            background: #1d4ed8;
            color: white;
            padding: 8px;
            z-index: 100;
            transition: top 0.2s;
        }
        .skip-link:focus {
            top: 0;
        }
        .radio-input:focus-visible + .radio-label {
            outline: 2px solid #1d4ed8;
            outline-offset: 4px;
            border-radius: 8px;
        }
    </style>
</head>
<body class="flex items-center justify-center min-h-screen p-4">
    <a href="#main-content" class="skip-link">Skip to main content</a>
    <div id="root" class="w-full max-w-md"></div>

    <script type="text/babel">
        const { useState, useRef, useEffect } = React;

        const RadioOption = ({ id, name, value, label, checked, onChange, isInvalid }) => (
            <div className="relative">
                <input
                    id={id}
                    type="radio"
                    name={name}
                    value={value}
                    checked={checked}
                    onChange={() => onChange(value)}
                    className="sr-only radio-input"
                    aria-invalid={isInvalid}
                />
                <label
                    htmlFor={id}
                    className={`radio-label flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all duration-200 ${
                        checked 
                            ? 'border-blue-600 bg-blue-50 shadow-sm' 
                            : 'border-slate-200 bg-white hover:border-slate-300'
                    }`}
                >
                    <span className={`w-5 h-5 mr-3 border-2 rounded-full flex items-center justify-center transition-colors ${
                        checked ? 'border-blue-600 bg-blue-600' : 'border-slate-300'
                    }`}>
                        {checked && <span className="w-2 h-2 bg-white rounded-full"></span>}
                    </span>
                    <span className="text-sm font-semibold text-slate-900">{label}</span>
                </label>
            </div>
        );

        const RadioButtonGroup = ({ legend, options, name, value, onChange, error }) => {
            const firstRadioRef = useRef(null);

            return (
                <div className="form-field">
                    <fieldset 
                        className="space-y-4"
                        aria-describedby={error ? `${name}-error` : undefined}
                    >
                        <legend className="text-lg font-bold text-slate-900 mb-4">
                            {legend} <span className="text-red-700" aria-hidden="true">*</span>
                        </legend>

                        {error && (
                            <p id={`${name}-error`} className="text-sm font-medium text-red-700 flex items-center mb-4" role="alert">
                                <svg className="w-4 h-4 mr-1.5" fill="currentColor" viewBox="0 0 20 20">
                                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                                </svg>
                                Error: {error}
                            </p>
                        )}

                        <div className="grid gap-3">
                            {options.map((option, index) => (
                                <RadioOption
                                    key={option.value}
                                    id={`${name}-${option.value}`}
                                    name={name}
                                    value={option.value}
                                    label={option.label}
                                    checked={value === option.value}
                                    onChange={onChange}
                                    isInvalid={!!error}
                                />
                            ))}
                        </div>
                    </fieldset>
                </div>
            );
        };

        const NotificationForm = () => {
            const [preference, setPreference] = useState('');
            const [status, setStatus] = useState('idle');
            const [error, setError] = useState('');
            const formRef = useRef(null);

            const handleSubmit = (e) => {
                e.preventDefault();
                setError('');

                if (!preference) {
                    setError('Please select a notification method.');
                    // Focus first radio button
                    const firstRadio = formRef.current.querySelector('input[type="radio"]');
                    if (firstRadio) firstRadio.focus();
                    return;
                }

                setStatus('submitting');

                // Simulate form submission
                setTimeout(() => {
                    setStatus('success');
                }, 800);
            };

            const options = [
                { label: 'Email', value: 'Email' },
                { label: 'SMS', value: 'SMS' },
                { label: 'Push Notifications', value: 'Push Notifications' }
            ];

            if (status === 'success') {
                return (
                    <div className="bg-white p-10 rounded-2xl shadow-xl border border-slate-100 text-center" role="status">
                        <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <svg className="w-8 h-8 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" />
                            </svg>
                        </div>
                        <h2 className="text-2xl font-bold text-slate-900 mb-3">Settings Saved</h2>
                        <p className="text-slate-600 mb-8 text-lg">We'll send your notifications via <strong>{preference}</strong>.</p>
                        <button 
                            onClick={() => {setStatus('idle'); setPreference(''); setError('');}}
                            className="inline-flex items-center px-6 py-3 border border-slate-200 text-base font-semibold rounded-xl text-slate-700 bg-white hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-colors"
                        >
                            Change Preferences
                        </button>
                    </div>
                );
            }

            return (
                <div id="main-content" className="bg-white p-10 rounded-2xl shadow-xl border border-slate-100">
                    <header className="mb-8">
                        <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">Notification Settings</h1>
                        <p className="text-slate-500 mt-2 text-lg">Choose how you'd like to stay in the loop.</p>
                    </header>

                    <form ref={formRef} onSubmit={handleSubmit} noValidate>
                        <RadioButtonGroup
                            legend="How do you prefer to receive notifications?"
                            name="notification-preference"
                            options={options}
                            value={preference}
                            onChange={(val) => { setPreference(val); setError(''); }}
                            error={error}
                        />

                        <button
                            type="submit"
                            className={`w-full py-4 px-6 rounded-xl font-bold text-white shadow-lg transition-all transform active:scale-[0.98] ${
                                status === 'submitting'
                                    ? 'bg-slate-400 cursor-not-allowed'
                                    : 'bg-blue-700 hover:bg-blue-800 hover:shadow-blue-200'
                            } focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2`}
                        >
                            {status === 'submitting' ? (
                                <span className="flex items-center justify-center">
                                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    Saving...
                                </span>
                            ) : 'Save Preferences'}
                        </button>
                    </form>
                </div>
            );
        };

        const App = () => (
            <main>
                <NotificationForm />
            </main>
        );

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
